def _size(key):
    try:
        from django.core.files.storage import default_storage
        from PIL import Image

        with default_storage.open(key, 'rb') as fh:
            return Image.open(fh).size
    except Exception:  # noqa: BLE001 - a missing file still becomes a version; the editor reads its size
        return 0, 0


def forwards(apps, schema_editor):
    ProjectPhoto = apps.get_model('core', 'ProjectPhoto')
    Version = apps.get_model('core', 'ProjectPhotoVersion')
    AiAction = apps.get_model('core', 'AiAction')

    for photo in ProjectPhoto.objects.filter(edited__isnull=False).select_related('edited'):
        if Version.objects.filter(photo=photo, file_id=photo.edited_id).exists():
            continue
        action, caption = OLD_KINDS.get(photo.edit_kind, ('', 'AI edit'))
        width, height = _size(photo.edited.key)
        Version.objects.create(
            photo=photo, kind='ai', action=action, caption=caption, file_id=photo.edited_id,
            thumbnail_id=photo.edited_thumbnail_id, width=width, height=height, status='done',
            made_by_id=photo.taken_by_id, made_at=photo.edited.uploaded_at,
        )

    for purpose, (label, description) in ACTIONS.items():
        AiAction.objects.get_or_create(purpose=purpose, defaults={
            'label': label, 'description': description, 'workspace': 'Processing', 'page': 'Photo projects',
            'modality': 'image', 'tier': 'image', 'effort': '',
        })


def backwards(apps, schema_editor):
    apps.get_model('core', 'AiAction').objects.filter(purpose__in=list(ACTIONS)).delete()


